B1 = dict(slug="ai-from-zero", title="الذكاء الاصطناعي من الصفر: الدليل الشامل للمبتدئ", sub="كل ما تحتاج لفهم الذكاء الاصطناعي واستخدامه بثقة", icon="🤖", level="مبتدئ", tag="أساسيات",
 desc="كتاب عربي شامل يشرح الذكاء الاصطناعي من الصفر: ما هو، كيف يعمل، أنواعه، النماذج اللغوية، حدوده، وكيف تستخدمه في يومك.",
 chapters=[
 ("ما هو الذكاء الاصطناعي فعلًا؟",["الذكاء الاصطناعي مجال في علوم الحاسب يهدف إلى بناء أنظمة تؤدي مهامًا كانت تحتاج عادة إلى ذكاء بشري، مثل فهم اللغة، وتمييز الصور، واتخاذ القرار، والتنبؤ. هو ليس كائنًا واعيًا ولا عقلًا بشريًا، بل برامج تتعلم أنماطًا من البيانات.","من المفيد التفريق بين مفهومين: الذكاء الاصطناعي الضيق الذي يتقن مهمة محددة (ترجمة، توصية أفلام، كشف احتيال) وهو كل ما نستخدمه اليوم، والذكاء الاصطناعي العام الذي يفترض أن يؤدي أي مهمة فكرية كالإنسان، وهو هدف بحثي لم يتحقق بشكل متفق عليه.","تجده في يومك دون أن تشعر: ترشيحات يوتيوب، تصحيح الإملاء، فتح الهاتف بالوجه، ردود الدعم الآلي، وكشف الاحتيال البنكي."],["الذكاء الاصطناعي برامج تتعلم الأنماط من البيانات","كل ما يُستخدم اليوم ذكاء ضيق متخصص","يظهر في تطبيقات يومية كثيرة"]),
 ("لمحة تاريخية: من الفكرة إلى الواقع",["بدأ المجال رسميًا في خمسينيات القرن الماضي حين طرح الباحثون سؤال: هل يمكن للآلة أن تفكر؟ ظهرت برامج تلعب الداما وتثبت نظريات، ثم مرّ المجال بفترات حماس وفترات ركود تُسمى «شتاء الذكاء الاصطناعي» حين لم تتحقق التوقعات.","تغيّر المشهد حين توفرت ثلاثة أمور معًا: بيانات ضخمة من الإنترنت، وقدرة حوسبة كبيرة عبر المعالجات الرسومية، وخوارزميات تعلم عميق أفضل. ثم جاءت بنية المحوّلات (Transformers) عام 2017 فأطلقت جيل النماذج اللغوية الكبيرة الذي بدأ الجمهور يستخدمه مباشرة في محادثات."],["المجال عمره عقود وتخللته فترات ركود","البيانات والحوسبة والخوارزميات صنعت الطفرة","المحوّلات أساس النماذج اللغوية الحديثة"]),
 ("كيف يتعلم الذكاء الاصطناعي؟ التعلم الآلي ببساطة",["بدل أن يكتب المبرمج قواعد تفصيلية، نعطي النظام أمثلة كثيرة ويتركه يستخرج القاعدة بنفسه. هذا هو التعلم الآلي. مثلًا: بدل شرح شكل القطة بالكلمات، نعرض آلاف الصور المعنونة فيتعلم النظام الأنماط المميزة.","هناك ثلاثة أنماط رئيسية: التعلم الموجَّه (أمثلة مع إجابات صحيحة)، والتعلم غير الموجَّه (اكتشاف مجموعات وأنماط دون إجابات)، والتعلم المعزَّز (تجربة وخطأ مع مكافآت). والتعلم العميق يستخدم شبكات عصبية متعددة الطبقات تستطيع تمثيل أنماط معقدة.","جودة النتيجة تعتمد على جودة البيانات: بيانات منحازة أو ناقصة تنتج نظامًا منحازًا أو ضعيفًا."],["التعلم الآلي يستخرج القواعد من الأمثلة","ثلاثة أنماط: موجَّه وغير موجَّه ومعزَّز","الجودة تبدأ من جودة البيانات"]),
 ("النماذج اللغوية الكبيرة: كيف يتحدث ChatGPT وClaude؟",["النموذج اللغوي الكبير شبكة عصبية دُرّبت على كميات هائلة من النصوص لتتنبأ بالكلمة (أو الجزء من الكلمة) التالية. وحين تتكرر هذه العملية يولّد نصًا مترابطًا يبدو كحوار. بعد التدريب الأولي يُحسَّن النموذج بتعليمات وبتقييمات بشرية ليكون مفيدًا وآمنًا.","النموذج لا «يبحث» في قاعدة معلومات كل مرة، بل يعتمد على أنماط تعلمها. ولذلك قد يخطئ بثقة، وهو ما يسمى «الهلوسة»: معلومات تبدو معقولة لكنها غير صحيحة.","يقرأ النموذج رسالتك داخل «نافذة سياق» محدودة الحجم، وما يخرج عن هذه النافذة لا يراه. وتقدّم بعض المنصات أدوات إضافية مثل البحث والملفات وتنفيذ الشيفرة."],["النموذج يتنبأ بالجزء التالي من النص","قد يخطئ بثقة (هلوسة) فتحقق دائمًا","السياق محدود ويحدد ما يراه النموذج"]),
 ("أنواع الذكاء الاصطناعي وتطبيقاته الرئيسية",["معالجة اللغة: ترجمة، تلخيص، كتابة، أسئلة وأجوبة. الرؤية الحاسوبية: تمييز الوجوه، قراءة الصور الطبية، مراقبة الجودة. الكلام: تحويل الصوت إلى نص والعكس. أنظمة التوصية: ما تشاهده وتشتريه. التنبؤ: الطلب والمبيعات والأعطال. التوليد: صور وصوت وفيديو ونصوص.","يمكن تصنيف التطبيقات إلى: تحليلية (تفهم وتتنبأ) وتوليدية (تنتج محتوى جديدًا). كلاهما مفيد في العمل، لكن الاعتماد عليهما يختلف: التحليلية تحتاج بيانات منظمة، والتوليدية تحتاج توجيهًا جيدًا ومراجعة."],["اللغة والرؤية والصوت والتوصية والتنبؤ والتوليد","تحليلي مقابل توليدي","لكل نوع متطلبات بيانات ومراجعة"]),
 ("أدوات الذكاء الاصطناعي التي تستخدمها اليوم",["مساعدات المحادثة العامة مثل ChatGPT وClaude وGemini تناسب الكتابة والتحليل والأفكار والبرمجة. أدوات البحث المدعومة بالذكاء الاصطناعي تجيب مع مصادر. أدوات الصور تنتج تصاميم من وصف. أدوات الصوت تحول الاجتماعات إلى نصوص وملخصات. وأدوات الأتمتة تربط التطبيقات ببعضها.","اختر الأداة بحسب المهمة لا بحسب الشهرة: مهمة كتابة؟ مساعد محادثة. تلخيص اجتماع؟ أداة نسخ صوتي. صورة إعلان؟ أداة صور. وقارن دائمًا الخصوصية والأسعار وشروط الاستخدام، فهي تتغير كثيرًا."],["اختر الأداة بحسب المهمة","جرّب أكثر من أداة وقارن","راجع الخصوصية والتكلفة دوريًا"]),
 ("كيف تتحدث مع الذكاء الاصطناعي: مدخل إلى البرومت",["البرومت هو التعليمات التي تكتبها. الوضوح هنا يساوي الجودة: حدّد الهدف والسياق والجمهور وشكل الناتج والقيود. بدل «اكتب لي إعلانًا» جرّب «اكتب 3 إعلانات لمتجر عطور للنساء 25-40، كل منها 40 كلمة، بنبرة أنيقة، دون وعود غير مؤكدة».","اطلب من النموذج أن يسألك إن نقصت معلومة، وأعطه مثالًا للناتج المطلوب، وعدّل بتعليمات محددة بعد المسودة الأولى. ولمعرفة المزيد راجع كتابنا المخصص للبرومت وأداة بناء البرومت في الموقع."],["الوضوح يرفع الجودة","السياق والشكل والقيود عناصر أساسية","التحسين التدريجي بعد المسودة"]),
 ("حدود الذكاء الاصطناعي ومخاطره",["من أهم الحدود: الأخطاء المقنعة، والتحيز الموروث من البيانات، ومحدودية المعرفة الحديثة، وصعوبة الحسابات الطويلة أحيانًا، وغياب الفهم الحقيقي للسياق الإنساني. ومن المخاطر: تسريب البيانات الحساسة، والاعتماد الزائد، والمعلومات المضللة، وانتحال الأعمال.","قواعد عملية: لا تُدخل بيانات سرية في أدوات غير مصرّح بها، وتحقق من الأرقام والاقتباسات، وأبقِ إنسانًا مسؤولًا عن القرار، وأفصح عن الاستعانة بالذكاء الاصطناعي حين يُطلب منك ذلك."],["الأخطاء والتحيز من أبرز الحدود","الخصوصية والاعتماد الزائد مخاطر عملية","المسؤولية تبقى بشرية"]),
 ("الذكاء الاصطناعي والوظائف: ماذا سيتغير؟",["الأرجح أن تتغير المهام داخل الوظائف أكثر من اختفاء الوظائف كاملة. المهام المتكررة القابلة للتوثيق تُؤتمت أولًا، فيما تزداد قيمة الحكم والإبداع والتواصل والمعرفة بالمجال والتحقق.","من يتعلم استخدام الأدوات في مجاله يرفع إنتاجيته ويصبح أكثر تنافسية. ابدأ بتحديد مهام أسبوعك المتكررة، ثم جرّب تسريع كل منها، وقِس الوقت الموفر وجودة الناتج."],["تتغير المهام قبل الوظائف","الحكم والتواصل والتحقق تزداد قيمتها","ابدأ بأتمتة مهامك المتكررة"]),
 ("خطة عملية لأول 30 يومًا",["الأسبوع الأول: افتح حسابًا في مساعد محادثة وجرّب 10 طلبات بسيطة في عملك أو دراستك. الأسبوع الثاني: تعلّم كتابة البرومت بإطار الهدف-السياق-الشكل-القيود. الأسبوع الثالث: ابنِ مكتبة من 10 قوالب تستخدمها بانتظام. الأسبوع الرابع: اختر مشروعًا صغيرًا (تقرير، حملة، دراسة) وأنجزه بمساعدة الأداة، وقِس الأثر.","واصل التعلم بالممارسة اليومية القصيرة، وراجع الأدوات الجديدة كل شهر، وشارك ما تعلمته مع فريقك."],["30 يومًا تكفي لبناء عادة","بناء مكتبة قوالب شخصية","قياس الأثر يثبت الفائدة"]),
 ])
B2 = dict(slug="ai-for-business-owners", title="الذكاء الاصطناعي لأصحاب الأعمال والمتاجر الإلكترونية", sub="من خدمة العملاء إلى المبيعات والتسويق والعمليات", icon="🛒", level="متوسط", tag="الأعمال",
 desc="كتاب تطبيقي لأصحاب المشاريع والمتاجر: كيف تستخدم الذكاء الاصطناعي في خدمة العملاء والتسويق والمبيعات والمحتوى والتحليل والعمليات وبناء الفريق، مع أمثلة وقوالب.",
 chapters=[
 ("أين يصنع الذكاء الاصطناعي فرقًا في مشروعك؟",["ابدأ من الألم لا من الأداة: ما المهام التي تأكل وقتك؟ غالبًا: الرد على العملاء، كتابة المحتوى، إعداد التقارير، متابعة المبيعات، وتنظيم الطلبات. اختر مهمة واحدة متكررة وقابلة للقياس وابدأ بها.","قيّم كل فكرة بمعيارين: التوفير المتوقع في الوقت أو المال، وكلفة الخطأ. المهام منخفضة الخطورة وكثيرة التكرار مثل صياغة الردود الأولية مثالية للبداية."],["ابدأ بمشكلة محددة","قيّم التوفير وكلفة الخطأ","مهمة واحدة أولًا ثم توسّع"]),
 ("خدمة العملاء بالذكاء الاصطناعي",["يمكن للنماذج صياغة ردود سريعة على الأسئلة المتكررة، وتصنيف الرسائل، واقتراح حلول للموظف. الأساس هو قاعدة معرفة واضحة: سياسات الشحن والإرجاع والأسعار والأسئلة الشائعة، ليعتمد عليها النموذج ولا يخترع وعودًا.","اجعل الإنسان يراجع الحالات الحساسة: التعويضات، الشكاوى القانونية، العملاء الغاضبون. وقِس: زمن الرد الأول، نسبة الحل من أول تواصل، رضا العميل."],["قاعدة معرفة تمنع الاختلاق","الحالات الحساسة بمراجعة بشرية","قِس الزمن والحل والرضا"]),
 ("التسويق والمحتوى",["استخدمه للبحث عن زوايا المحتوى، وكتابة مسودات الإعلانات بصيغ مختلفة، وإعداد تقويم محتوى، وتحويل مقال إلى عدة منشورات، وتحليل تعليقات العملاء لاستخراج الاعتراضات. ثم اختبر بميزانية صغيرة.","لا تنشر ما لم تراجعه: تأكد من صحة الادعاءات، ولا تخترع شهادات أو أرقامًا. ما يميز علامتك هو صوتك وخبرتك، فأعطِ النموذج عينات من كتابتك."],["الذكاء الاصطناعي يسرّع المسودات لا الحقيقة","اختبر الأفكار بميزانية صغيرة","حافظ على صوت علامتك"]),
 ("المبيعات والتفاوض",["يساعدك في بناء شخصيات العملاء، وتحضير ردود الاعتراضات، وكتابة رسائل المتابعة، وتلخيص مكالمات المبيعات واستخراج الخطوات التالية. وفي المتاجر يساعد على تحسين وصف المنتج وصفحات الهبوط.","جرّب قالب الاعتراض: اكتب أكثر 5 اعتراضات تسمعها واطلب رد 40 كلمة لكل اعتراض بنبرة محترمة ودون وعود خارج السياسة، ثم عدّلها بصوتك."],["الاعتراضات والمتابعة من أفضل الاستخدامات","لخّص المكالمات واستخرج المهام","عدّل الردود بصوتك"]),
 ("تحليل البيانات واتخاذ القرار",["ارفع جدول مبيعاتك (بعد إخفاء البيانات الحساسة) واسأل أسئلة محددة: ما أفضل المنتجات نموًا؟ أي أسبوع شاذ؟ أي قناة أرخص تكلفة اكتساب؟ واطلب طريقة الحساب لتتحقق.","الذكاء الاصطناعي يقترح فرضيات، والقرار يحتاج تحققًا. قارن عينة من الأرقام يدويًا، واختبر التوصيات بتجارب صغيرة."],["أسئلة محددة أفضل من «حلل»","اطلب طريقة الحساب","اختبر التوصيات قبل التعميم"]),
 ("العمليات والمخزون وسلسلة التوريد",["تنبؤ الطلب، تحديد حدود إعادة الطلب، كشف الأصناف الراكدة، ومقارنة الموردين كلها مجالات مناسبة. ابدأ بجداول بسيطة وحاسبات: الهامش، نقطة التعادل، تكلفة الاكتساب، قبل الأنظمة المعقدة.","وثّق إجراءاتك (SOP) بمساعدة الذكاء الاصطناعي: اطلب منه تحويل ملاحظاتك إلى خطوات واضحة وقوائم تحقق يتبعها الفريق."],["ابدأ بحاسبات وجداول بسيطة","وثّق الإجراءات كقوائم تحقق","التنبؤ يحسن المخزون لكنه ليس مضمونًا"]),
 ("بناء الفريق والموارد البشرية",["يساعد في صياغة الوصف الوظيفي، وأسئلة المقابلات، وخطط التهيئة، وتقييم الأداء. لكن لا تدعه يقرر التوظيف أو الفصل، ولا تُدخل بيانات الموظفين التعريفية. استخدمه كمساعد صياغة وتنظيم.","درّب فريقك على قواعد استخدام واضحة: ما المسموح، وما البيانات الممنوعة، وكيف تُراجع المخرجات."],["مساعد صياغة لا صانع قرار","احمِ بيانات الموظفين","سياسة استخدام مكتوبة للفريق"]),
 ("الأتمتة: اربط أدواتك",["أدوات الأتمتة تربط الطلبات والجداول والبريد والمراسلة: عند وصول طلب جديد، يُسجَّل في جدول ويُرسل إشعار ويُصاغ رد أولي. ابدأ بسير عمل واحد بسيط، واختبره أسبوعًا، ثم وسّع.","احرص على نقطة موافقة بشرية قبل أي إجراء مالي أو مراسلة للعميل، وعلى سجل لما يحدث."],["سير عمل واحد أولًا","موافقة بشرية قبل الإجراءات الحساسة","احتفظ بسجل"]),
 ("الخصوصية والامتثال",["اعرف أي البيانات تُرسل إلى الأداة ومن يخزنها. لا تُدخل بيانات عملاء الشخصية أو الأسرار التجارية في أدوات غير معتمدة. راجع سياسة الخصوصية وشروط الاستخدام وخيارات الأعمال.","اتبع أنظمة بلدك لحماية البيانات، واطلب مشورة قانونية في العقود والمسائل الحساسة."],["اعرف أين تذهب بياناتك","استخدم خطط الأعمال عند الحاجة","استشر مختصًا في الأمور النظامية"]),
 ("خطة 90 يومًا لتحويل مشروعك",["الشهر الأول: اختر مهمتين وقِس الوضع الحالي. الشهر الثاني: طبّق الأدوات على المهمتين وراجع الجودة. الشهر الثالث: وسّع لمهمتين إضافيتين وأعدّ دليلًا داخليًا للقوالب والقواعد. قِس: الوقت الموفر، الأخطاء، رضا العميل، التكلفة.","ولا تنس أن الميزة التنافسية الدائمة هي معرفتك بعملائك وجودة منتجك؛ الأداة مسرّع لا بديل."],["قياس قبل وبعد","وسّع تدريجيًا","الميزة في معرفتك وجودتك"]),
 ])
